package com.smarthub.plus;import org.junit.Test;import org.json.*;import java.io.IOException;import static org.junit.Assert.*;public class FirmwareCaRequestTest{private JSONObject body()throws Exception{return new JSONObject().put("pmt_pid",628);}private JSONArray services()throws Exception{return new JSONArray().put(new JSONObject().put("sid",519).put("pmt",628).put("ca",64));}@Test public void usesOrdinaryCaMetadataWithoutForcedOverride()throws Exception{JSONObject b=body();FirmwareCaRequest.apply(b,64,new JSONArray().put(2317).put(2352),services());assertEquals(64,b.getInt("iCAType"));assertEquals(1,b.getInt("pt_enable"));assertEquals(0,b.getInt("force_CA_B"));assertEquals("02070274",b.getString("pucPmtPids"));assertEquals("0207",b.getString("pucSids"));}@Test(expected=IOException.class)public void missingCaMetadataCannotBeGuessed()throws Exception{FirmwareCaRequest.apply(body(),64,new JSONArray(),services());}@Test public void freeChannelsDoNotEnableCa()throws Exception{JSONObject b=body();FirmwareCaRequest.apply(b,0,null,null);assertFalse(b.has("pt_enable"));}}